use system.collections.list

fn double_all(values List<int>) List<int>
    var result = List<int>()
    for v in values
        result.push(v * 2)
    result

fn main()
    let nums = List([1, 2, 3, 4])
    let doubled = double_all(nums)
    var total = 0
    for d in doubled
        total += d
    println(f"doubled={doubled} total={total}")

